"use strict";
/* ---------- The Art of the Shell (dojo communautaire, open source BSD-2-Clause) ----------
   Source : dojo « shell-lin-do » lu sur staging.pwn.college et son dépôt public
   le 18 novembre 2026 — 5 modules, 55 défis, aucun verrouillé, effectifs conformes.
   Sur le site, chaque défi n'a qu'une description d'une ligne : les leçons décrivent
   le concept shell enseigné, jamais de solution pas à pas. */
var DOJO_AOS_LESSONS = [
  { id:"AOS-01", mod:"The Beginning", t:"Le shell est un art : PATH, builtins et $0", sub:"Module The Beginning : 3 défis — The Transient Path, Ferocious Functionality, The Surprising Swap. Les ressources du module : le manuel Bash, le wiki wooledge, la documentation Apple sur la sécurité des scripts shell.",
    read:["The Art of the Shell ouvre sur une déclaration d’intention : le shell n’est pas un simple outil de commandes, c’est un langage complet, avec ses pièges — et ce dojo, open source, est entièrement consacré à sa sécurité. Le premier module, The Beginning, pose trois idées fondatrices. La première : quand tu tapes une commande, le shell la cherche dans les répertoires listés par la variable PATH, dans l’ordre. Le premier défi lance la commande fortune via sh en s’appuyant sur ce chemin — or un chemin de recherche peut changer : une commande trouvée à un moment peut ne plus l’être ensuite, ou être remplacée par une autre du même nom placée plus tôt dans la liste.",
      "Le deuxième défi vide complètement le PATH (unset PATH) : les programmes externes deviennent introuvables, mais le shell continue de fonctionner — ses commandes internes (builtins) et les fonctions qu’on lui a définies sont exécutées par lui-même, sans recherche dans le système de fichiers. Distinguer ce qui vit dans le shell de ce qui vit sur le disque est la première carte à apprendre. Le troisième défi joue sur l’identité : un script se ré-invoque lui-même via $0, le nom sous lequel il a été appelé — et ce nom peut être déguisé, par un lien symbolique ou un lancement sous un autre nom.",
      "Les trois leçons de défense tiennent en une phrase chacune : pour une commande critique, préfère son chemin absolu plutôt que de faire confiance au PATH du moment ; sache quelles commandes sont des builtins, car elles survivent à un environnement dégradé ; et ne décide jamais du comportement d’un script d’après $0, son nom d’appel, qui est une étiquette, pas une identité. Les ressources du module disent la même chose : le shell pardonne peu, mais il est prévisible pour qui connaît ses règles."],
    term:"$ echo $PATH\n/usr/local/bin:/usr/bin:/bin\n<span class=\"tdim\">Le chemin de recherche des commandes, dans l’ordre. Le shell prend la première correspondance — c’est toute la fragilité, et toute la puissance, du mécanisme.</span>",
    ex:{ type:"qcm", q:"Pourquoi un script critique devrait-il appeler ses commandes par leur chemin absolu ?",
      opts:["Parce que les chemins absolus s’exécutent plus vite", "Parce que le PATH peut changer ou contenir un répertoire contrôlé par quelqu’un d’autre : la commande trouvée par son nom seul n’est pas forcément celle qu’on croit lancer", "Parce que les builtins disparaissent quand le PATH est vidé"], ok:1 },
    why:"Le PATH est une liste de recherche ordonnée : le premier répertoire qui contient le nom gagne. Un répertoire inscriptible placé tôt suffit à interposer une fausse commande, et un PATH vidé rend les programmes externes introuvables — seuls les builtins et les fonctions survivent, comme le montre le deuxième défi. Le chemin absolu court-circuite la recherche ; c’est le réflexe des scripts critiques." },
  { id:"AOS-02", mod:"Abusing Expansion", t:"La variable non citée : découpage et globbing dans les tests", sub:"Module Abusing Expansion (22 défis), défis 1 et 12 : Path of the Unquoted et Your Shattered Sanity — le test [ $1 = “flag” ] et le test [ -f $1 ].",
    read:["Le module Abusing Expansion compte 22 défis : c’est le cœur du dojo, entièrement consacré à ce que le shell fait à tes mots avant que la commande ne les voie. Le premier piège est le plus célèbre de tous : la variable non citée. Dans le test [ $1 = “flag” ], si l’argument $1 contient des espaces, le shell le découpe en plusieurs mots — le word splitting ; s’il contient un caractère comme *, le shell le remplace par les noms de fichiers correspondants du répertoire courant — le globbing. Le test ne compare donc plus la valeur reçue, mais ses morceaux éclatés, ou la liste des fichiers présents.",
      "Le défi 12 pousse le même mécanisme sur un test de fichier, [ -f $1 ] : l’argument est « brisé » en mots par le découpage, et le test ne voit que le premier morceau — le reste devient des arguments en trop, ou une erreur de syntaxe du test. Dans les deux cas, la cause est identique et la parade aussi : citer la variable — [ “$1” = “flag” ], [ -f “$1” ] — pour que le shell la transmette comme un seul mot, exactement telle qu’elle a été reçue.",
      "Retiens la règle générale, elle reviendra dans tout le dojo : en shell, l’absence de guillemets n’est pas une neutralité, c’est une demande d’expansion. Chaque variable non citée est réinterprétée — découpée, globbée — au moment de l’emploi. C’est pour cela que les ressources du module sont la référence des expansions du shell et la page man 7 glob : savoir dans quel ordre le shell transforme une ligne, c’est savoir lire n’importe quel script."],
    term:"[ $1 = \"flag\" ]   ← dangereux : $1 est découpé et globbé avant le test\n[ \"$1\" = \"flag\" ] ← sûr : un seul mot, la valeur exacte\n<span class=\"tdim\">Même test, deux sémantiques. Les guillemets ne décorent pas : ils décident de ce que le shell a le droit de transformer.</span>",
    ex:{ type:"qcm", q:"Que se passe-t-il quand une variable contenant des espaces est utilisée sans guillemets dans un test [ ] ?",
      opts:["Le shell la traite comme un seul mot, comme avec des guillemets", "Elle subit le découpage en mots et l’expansion des globs : le test reçoit plusieurs mots — ou des noms de fichiers — au lieu de la valeur", "Le script refuse de démarrer avec une erreur de syntaxe"], ok:1 },
    why:"C’est le mécanisme n°1 des scripts fragiles : sans guillemets, le shell réinterprète la valeur — découpage sur les espaces, puis remplacement des motifs par des fichiers. Le test reçoit alors autre chose que ce que l’utilisateur a passé, et ses conclusions sont fausses dans un sens imprévisible. Citer la variable est la parade entière : un seul mot, la valeur exacte, ni découpage ni glob." },
  { id:"AOS-03", mod:"Abusing Expansion", t:"Le glob qui mange le motif, et $* contre “$@”", sub:"Défis 2 et 3 : Globbing Harmony et Zen of Expansion — tr reçoit des noms de fichiers au lieu du motif écrit ; une fonction reçoit $* et voit ses arguments redécoupés.",
    read:["Le défi 2 montre le globbing en pleine action, dans une commande qui a l’air anodine : cat /flag | tr -d [A-Za-z0-9] — supprimer du flag toutes les lettres et chiffres. Mais le motif [A-Za-z0-9] n’est pas cité : avant même que tr ne démarre, le shell l’interprète comme un motif glob et le remplace par les noms de fichiers du répertoire courant qui correspondent — ici, ceux du répertoire temporaire. tr ne reçoit donc jamais le motif écrit : il reçoit des noms de fichiers, et supprime de tout autres caractères. Le sens d’une commande non citée dépend des fichiers présents : change le répertoire, la commande change.",
      "Le défi 3 change d’angle : une fonction reçoit $* non cité. $* commence par joindre tous les arguments en une seule chaîne, puis — faute de guillemets — le résultat est redécoupé en mots et globbé. Un seul argument contenant un espace devient ainsi plusieurs paramètres : dans le défi, un en-tête et un nom de fichier là où l’appelant n’avait passé qu’une valeur. La forme correcte est “$@” : entre guillemets, elle transmet chaque argument exactement tel quel, un par un, sans jointure ni redécoupage.",
      "Ces deux défis enseignent la même vigilance sous deux formes : le shell étend d’abord, la commande reçoit ensuite. Quand tu lis un script, la bonne question n’est pas « que dit ce motif ? » mais « que va-t-il devenir après expansion, dans ce répertoire, avec ces valeurs ? ». L’ordre des transformations du shell — accolades, tilde, paramètres, arithmétique, substitution, découpage, glob — est la grammaire invisible de chaque ligne."],
    term:"tr -d [A-Za-z0-9]   ← le motif devient des noms de fichiers du répertoire\ntr -d \"[A-Za-z0-9]\" ← le motif arrive intact à tr\n<span class=\"tdim\">Un glob non cité ne décrit plus un motif : il énumère des fichiers. Les guillemets rendent au motif son sens.</span>",
    ex:{ type:"qcm", q:"Quelle est la différence entre $* et “$@” quand une fonction transmet ses arguments ?",
      opts:["Aucune : les deux transmettent les arguments à l’identique", "$* joint les arguments en une chaîne qui sera redécoupée si elle n’est pas citée ; “$@” préserve chaque argument tel quel, un par un", "$@ supprime les arguments contenant des espaces"], ok:1 },
    why:"Jointure puis redécoupage, contre transmission fidèle : toute la différence tient là. Un argument « rapport final.txt » passé par $* non cité arrive en deux mots — et le programme traite le premier comme le fichier, ou l’en-tête, et le second comme autre chose. “$@” est la seule forme qui respecte la frontière entre les arguments telle que l’appelant l’a posée." },
  { id:"AOS-04", mod:"Abusing Expansion", t:"[[ ]] : le côté droit est un motif, pas une chaîne", sub:"Défis 4, 13 et 14 : Way of the Wildcard, Untrustworthy Utterances, Echoes in Silence — pattern matching des doubles crochets et substitutions de commandes.",
    read:["Le défi 4 déplace le piège dans les doubles crochets : [[ “$FLAG” = $1 ]]. Dans [[ ]], il n’y a ni découpage en mots ni globbing des variables — c’est leur grand progrès sur [ ]. Mais le membre de droite d’une comparaison, s’il n’est pas cité, n’y est pas une chaîne littérale : c’est un motif glob. Comparer une valeur à un motif, ce n’est pas vérifier une égalité, c’est vérifier une correspondance — un motif comme * correspond à presque tout. Citer le membre de droite rend la comparaison littérale ; le laisser nu la transforme en recherche de motif.",
      "Les défis 13 et 14 ajoutent la substitution de commande. Dans [ $(cat “$1”) = $(cat /flag) ], les deux $(...) non cités subissent découpage et globbing : la comparaison porte sur des mots éclatés, pas sur le contenu des fichiers. Dans [[ $(cat /flag) = $(cat “$1”) ]], le découpage disparaît — [[ ]] oblige — mais le côté droit reste un motif, et une autre subtilité s’ajoute : la substitution de commande supprime les retours à la ligne finaux, donc même une comparaison « au contenu » compare des contenus déjà rognés.",
      "La leçon de défense est une discipline de lecture : pour chaque comparaison d’un script, demande-toi de quel type elle est — littérale ou par motif — et ce que le shell a déjà transformé avant elle. Les erreurs de ce module ne sont jamais des fautes de frappe : ce sont des sémantiques différentes de celles que l’auteur croyait avoir écrites."],
    term:"[[ \"$FLAG\" = $1 ]]    ← $1 est un motif : * correspond à presque tout\n[[ \"$FLAG\" = \"$1\" ]]  ← comparaison littérale, caractère par caractère\n<span class=\"tdim\">Dans [[ ]], les guillemets du côté droit choisissent entre motif et littéral. C’est un interrupteur de sémantique, pas une coquetterie.</span>",
    ex:{ type:"qcm", q:"Dans une comparaison [[ ... = ... ]] dont le membre de droite n’est pas cité, que compare-t-on réellement ?",
      opts:["Deux chaînes, caractère par caractère", "La valeur de gauche à un motif glob : le membre de droite non cité est un motif, où * et ? ont un sens spécial", "Les deux fichiers nommés par les variables"], ok:1 },
    why:"[[ ]] supprime le découpage et le globbing des variables, mais pas le pattern matching : c’est sa fonction même. Non cité, le membre de droite est lu comme un motif — une valeur contenant * « égale » alors presque n’importe quoi. Le citer force la comparaison littérale. Et dans les deux formes de test, la substitution de commande $(...) rogne les retours à la ligne finaux : même le contenu comparé n’est jamais tout à fait le contenu du fichier." },
  { id:"AOS-05", mod:"Abusing Expansion", t:"-eq évalue, il ne compare pas des chaînes", sub:"Défis 5 et 11 : Saga of the Sneaky Similarity et Tale of the Test — l’évaluation arithmétique des opérandes, et le test à logique inversée.",
    read:["Les défis 5 et 11 attaquent les tests numériques. Dans [ $1 -eq “$CHALLENGE” ], où la cible est un nombre aléatoire, l’opérateur -eq ne compare pas des chaînes : il évalue ses opérandes arithmétiquement. Or, en contexte arithmétique, un mot n’est pas lu comme du texte mais comme un nom de variable dont on prend la valeur — récursivement. Une entrée qui « n’est pas un nombre » peut donc valoir le contenu d’une variable du même nom, ou zéro, et le test répond vrai là où une comparaison de chaînes répondrait faux.",
      "Le défi 11 inverse la logique pour forcer la relecture : [[ “$1” -eq 1337 ]] rejette la valeur 1337 et accepte toute autre. Rien de sorcier dans le code — juste un test dont le sens réel est l’inverse de celui qu’un lecteur pressé lui prête, amplifié par l’évaluation arithmétique des opérandes : une chaîne non numérique y vaut 0, ou la valeur d’une variable homonyme. Deux pièges distincts, donc : la sémantique cachée de -eq, et la confiance aveugle dans le sens apparent d’un test.",
      "Côté défense : pour comparer des nombres, valider d’abord que l’entrée est bien un nombre — une expression régulière ou un test dédié — et ne jamais laisser une donnée extérieure entrer dans un contexte arithmétique sans ce contrôle. Et relire chaque test en se demandant ce qu’il accepte, pas seulement ce qu’il rejette : beaucoup de portes dérobées de scripts sont des tests corrects au service d’une logique inversée."],
    term:"[ $1 -eq \"$CHALLENGE\" ] ← -eq évalue ses opérandes arithmétiquement\n<span class=\"tdim\">En contexte arithmétique, un mot vaut le contenu de la variable du même nom. Le test « numérique » lit des variables, pas des chaînes.</span>",
    ex:{ type:"qcm", q:"Que fait l’opérateur -eq d’une opérande qui contient un mot plutôt qu’un nombre ?",
      opts:["Il la rejette toujours avec une erreur", "Il l’évalue arithmétiquement : le mot est lu comme un nom de variable et remplacé par sa valeur — ou par 0 s’il n’en a pas", "Il compare les chaînes caractère par caractère"], ok:1 },
    why:"Contexte arithmétique, règles arithmétiques : un nom y vaut le contenu de la variable du même nom. C’est ce qui rend les tests numériques perméables aux entrées texte — et c’est le même mécanisme qui, dans les défis des (( )), deviendra une surface d’injection complète. Valider le format avant le test n’est pas de la paperasse : c’est fermer la porte à cette réinterprétation." },
  { id:"AOS-06", mod:"Abusing Expansion", t:"Le lanceur declare : confier une variable, c’est confier le programme", sub:"Défis 6 et 7 : Enigma of the Environment et Voyage of the Variable — la famille du lanceur commence : nom et valeur d’environnement libres, puis le nom exact interdit.",
    read:["Les défis 6 à 10 forment une famille : un même « lanceur » revient, avec une protection de plus à chaque défi. Le principe de base, défi 6 : le lanceur laisse l’utilisateur choisir un nom et une valeur de variable d’environnement — via declare — puis exécute $PROGRAM non cité. Qui contrôle une variable contrôle son expansion au moment de l’emploi : découpage et globbing s’appliquent à la valeur choisie, et le « programme » exécuté devient celui que la valeur désigne. Confier une variable d’environnement à l’utilisateur, c’est lui confier la ligne de commande.",
      "Le défi 7 interdit le nom exact PROGRAM. Mais le shell connaît l’expansion indirecte : une variable peut en désigner une autre — ${!nom} lit la variable dont le nom est contenu dans une autre. Interdire un nom ne sert donc à rien quand le langage offre un détour officiel pour atteindre la même cible par référence. C’est une leçon qui dépasse le shell : un filtre qui bloque l’orthographe d’une chose sans bloquer les moyens de la désigner ne bloque rien.",
      "La défense, elle, change de nature : ne pas filtrer les noms, mais ne jamais construire une exécution à partir de variables fournies de l’extérieur. Une liste blanche de programmes — un case qui associe chaque choix autorisé à un chemin absolu écrit dans le script — remplace avantageusement tous les filtres : ce qui n’est pas listé n’existe pas, et aucune expansion ne peut inventer une entrée qui n’y est pas."],
    term:"declare \"$nom=$valeur\"   ← l’utilisateur choisit la variable\n$PROGRAM                   ← puis sa valeur est ré-expandue, non citée\n<span class=\"tdim\">Le lanceur des défis 6 à 10. Deux expansions offertes à l’extérieur : c’est deux expansions de trop.</span>",
    ex:{ type:"qcm", q:"Pourquoi interdire le nom exact PROGRAM ne protège-t-il pas le lanceur du défi 7 ?",
      opts:["Parce que le filtre contient une faute de frappe", "Parce que l’expansion indirecte permet de désigner la même variable par l’intermédiaire d’une autre : le nom est atteint sans jamais être écrit", "Parce que declare ignore toutes les interdictions"], ok:1 },
    why:"Un filtre par nom protège une orthographe, pas une cible. ${!nom} est la voie de référence du shell pour atteindre une variable dont on ne connaît le nom qu’à l’exécution — exactement le cas du lanceur. La parade n’est pas un meilleur filtre, c’est une autre architecture : liste blanche de choix, chemins absolus écrits dans le script, et aucune variable extérieure dans le chemin d’exécution." },
  { id:"AOS-07", mod:"Abusing Expansion", t:"Filtrer un nom ne suffit pas : délimiteurs et troncature", sub:"Défis 8, 9 et 10 : Dance of the Delimiters, Symphony of Separation, Saga of Sanitization — le filtre par motif, la variante du répertoire temporaire, et la désinfection par troncature.",
    read:["Le défi 8 durcit le lanceur : tout nom contenant PROGRAM est filtré. Le champ de bataille devient alors la grammaire même de l’analyse bash — les délimiteurs. Espaces, signe =, crochets des tableaux : le shell découpe et reconnaît les noms selon ses propres règles, qui ne coïncident pas forcément avec celles du filtre. Un nom que le filtre ne reconnaît pas comme « contenant PROGRAM » peut néanmoins être analysé par bash comme désignant la variable visée. Le défi 9 rejoue la même partie avec une difficulté supplémentaire : le répertoire temporaire au nom prévisible, /tmp/tmpXXXXXXX, entre dans l’équation.",
      "Le défi 10 change de stratégie de défense : au lieu d’interdire, le nom est tronqué au premier caractère interdit, puis testé avec [[ -v ... ]] — la variable est-elle déjà définie ? Mais désinfecter en tronquant ne supprime pas le danger : la valeur tronquée peut encore désigner une variable sensible, et le test d’existence ne dit rien de ce que l’expansion fera ensuite. Tronquer, c’est parier que le morceau restant est inoffensif — un pari que la grammaire du shell se charge souvent de faire perdre.",
      "La famille du lanceur se referme sur un principe d’audit : toute défense qui repose sur la forme d’une donnée — son nom, ses caractères, sa longueur — doit être relue avec la grammaire exacte de l’outil qui la consommera. Filtre et shell n’analysent pas de la même façon ; tout l’espace entre les deux analyses est un espace d’attaque. C’est vrai pour bash, et ce sera vrai pour chaque filtre que tu rencontreras — SQL, HTML, chemins de fichiers."],
    ex:{ type:"order", q:"Remets dans l’ordre la montée des protections du lanceur declare :",
      items:["Le lanceur de base : nom et valeur libres, exécution de la variable non citée", "Le nom exact PROGRAM est interdit", "Tout nom contenant PROGRAM est filtré", "Le nom est tronqué au premier caractère interdit, puis testé avec [[ -v ... ]]"],
      disp:[2,0,3,1] },
    why:"Chaque défi ajoute exactement une protection au même lanceur — et chaque protection tombe sur un mécanisme du shell : l’indirection contre l’interdiction du nom, les délimiteurs contre le filtre par motif, la désignation résiduelle contre la troncature. La progression est la leçon : empiler des filtres de forme ne converge pas vers la sécurité, parce que l’attaquant joue avec la grammaire, pas avec les intentions du filtre." },
  { id:"AOS-08", mod:"Abusing Expansion", t:"case, $0 et le format de printf", sub:"Défis 15 et 16 : Masquerade of the Self et Journey of the PATH — la branche par défaut qui relance le script, et printf dont le premier argument est un format.",
    read:["Le défi 15 revient sur l’identité : une structure case trie sur $1, et sa branche par défaut relance le script via $0 help. On retrouve le piège du module The Beginning : $0 est le nom d’appel, déguisable par un lien symbolique ou un lancement renommé. Un programme qui se relance lui-même par $0 peut donc être détourné vers un autre programme que lui-même — la branche « aide » devient une porte.",
      "Le défi 16 enchaîne deux pièges d’outils du quotidien. D’abord printf $1, non cité : le premier argument de printf n’est pas un texte à afficher, c’est une chaîne de format — %s, %d et les séquences d’échappement y sont interprétés. Passer une entrée extérieure comme format, c’est lui donner le contrôle de l’interprétation. Ensuite grep -f /flag : l’option -f fait lire à grep ses motifs dans un fichier — ici, le flag lui-même devient la liste des motifs à rechercher. Deux commandes banales, deux lectures « à l’envers » de ce qu’on croyait leur donner.",
      "La défense tient en deux réflexes : printf “%s” “$1” — un format fixe, écrit par le programmeur, et la donnée en argument, toujours ; et se méfier de toute option qui change la nature d’un argument — -f transforme un nom de fichier en contenu, comme d’autres options transforment une donnée en code. Quand tu audites un script, les options sont aussi importantes que les commandes : c’est souvent là que le sens bascule."],
    term:"printf $1          ← $1 devient la chaîne de format : %s y est interprété\nprintf \"%s\" \"$1\" ← format fixe, donnée en argument : rien à interpréter\n<span class=\"tdim\">Ne jamais passer une entrée extérieure comme format de printf. Le format est du code ; la donnée doit rester une donnée.</span>",
    ex:{ type:"qcm", q:"Pourquoi passer une entrée comme premier argument de printf est-il dangereux ?",
      opts:["Parce que printf affiche alors l’entrée deux fois", "Parce que le premier argument de printf est une chaîne de format : les %s, %d et échappements de l’entrée sont interprétés au lieu d’être affichés", "Parce que printf supprime les guillemets de l’entrée"], ok:1 },
    why:"Tout tient à la place : premier argument, printf lit un programme d’affichage ; en argument d’un %s fixe, la même entrée n’est que du texte. C’est la même distinction qu’entre code et données partout en sécurité — et grep -f, dans le même défi, la rejoue : un fichier de motifs n’est plus un fichier comme les autres dès qu’une option décide de le lire comme des instructions de recherche." },
  { id:"AOS-09", mod:"Abusing Expansion", t:"(( )) : l’arithmétique est une surface d’injection", sub:"Défis 17 et 20 : Secrets of the Shell et The Commanded Condition — la comparaison arithmétique, ses protections actives, puis les mêmes protections commentées.",
    read:["Les défis 17 à 21 forment la deuxième grande famille du module : la comparaison arithmétique (( RESPONSE == CHALLENGE )). Dans (( )), les noms de variables sont évalués arithmétiquement — et cette évaluation est récursive : la valeur d’une variable peut elle-même contenir un nom, une expression, voire une référence de tableau dont l’indice déclenche une substitution de commande. Autrement dit, une donnée extérieure placée dans un contexte arithmétique n’y est pas qu’un nombre : c’est une expression en puissance.",
      "Le défi 17 montre l’arsenal défensif que cette réalité impose : set -T, la variable BASH_SUBSHELL forcée en lecture seule, et un piège DEBUG qui fait quitter les sous-shells — trois verrous dont le seul but est d’empêcher qu’une commande s’exécute pendant l’évaluation arithmétique. Le défi 20 montre l’envers : les mêmes protections, présentes dans le code mais commentées, désactivées. La faille n’y est pas dans l’algorithme — elle est dans l’écart entre la protection écrite et la protection active.",
      "La leçon déborde largement le shell : une protection désactivée « temporairement », un verrou commenté pour déboguer, un contrôle laissé en place mais inactif — ce sont des failles à part entière, et des classiques des audits réels. Quand tu lis un script, ne demande pas seulement « la protection existe-t-elle ? », mais « est-elle active, ici, sur ce chemin d’exécution ? »."],
    ex:{ type:"qcm", q:"Dans le défi 20, où se trouve la faille ?",
      opts:["Dans l’algorithme de comparaison, qui est faux", "Dans les protections : elles existent dans le code mais sont commentées, donc inactives — l’évaluation arithmétique redevient une surface d’injection", "Dans le nom des variables, trop prévisible"], ok:1 },
    why:"Un contrôle commenté ne contrôle rien. Les protections du défi 17 — piège DEBUG, BASH_SUBSHELL en lecture seule, set -T — n’ont de valeur qu’actives ; leur version commentée du défi 20 laisse l’évaluation arithmétique libre d’exécuter ce que les données contiennent. En audit, « présent mais inactif » vaut « absent », avec un faux sentiment de sécurité en prime." },
  { id:"AOS-10", mod:"Abusing Expansion", t:"RANDOM, readonly, indices : les règles spéciales", sub:"Défis 18, 19, 21 et 22 : The Swap Scheming, Shell Sorcery, The Dreadful Discovery, Index of Insanity — la cible qui bouge, le verrou et sa fondation, l’indice de tableau.",
    read:["Le défi 18 compare (( RESPONSE == RANDOM )). RANDOM est une variable spéciale : chaque lecture produit un nouveau nombre pseudo-aléatoire. Comparer à une cible qui change à chaque lecture n’a pas la sémantique qu’on imagine — et l’indice du défi ajoute une couche : le comportement dépend du shell exact, le bash du dojo étant /bin/bash ; préparer son raisonnement dans un autre shell, c’est risquer de tester autre chose que ce qui tournera. Les variables spéciales ont des règles propres : RANDOM, SECONDS, LINENO ne se lisent pas comme des variables ordinaires.",
      "Le défi 19 verrouille la cible en lecture seule (readonly) dans la même structure de comparaison. Verrouiller une variable empêche de la réassigner — cela ne verrouille ni la façon dont elle est comparée, ni l’évaluation arithmétique qui l’entoure. Le défi 21 pousse le raisonnement un cran plus loin : les protections y reposent sur BASH_SUBSHELL, mais cette variable n’y est pas en lecture seule — elle peut être réassignée, et le piège qu’elle soutient neutralisé. Une protection n’est solide que si ses propres fondations le sont.",
      "Le défi 22 clôt le module sur les tableaux : dans ${PROPAGANDA[$INDEX]}, l’indice n’est pas « juste un nombre » — il est évalué arithmétiquement, avec tout ce que cela implique : expressions, indices négatifs qui comptent depuis la fin, noms de variables résolus. C’est le fil rouge du module entier : en shell, presque tout contexte « numérique » est un contexte d’évaluation, et toute donnée qui y entre doit être traitée comme une expression jusqu’à preuve du contraire."],
    ex:{ type:"order", q:"Remets dans l’ordre les couches attaquées par ces quatre défis, de la cible à la fondation :",
      items:["RANDOM produit une nouvelle valeur à chaque lecture : la cible bouge", "readonly verrouille la variable, pas la comparaison qui l’entoure", "La protection repose sur BASH_SUBSHELL, réassignable : la fondation bouge", "L’indice de tableau est évalué arithmétiquement : même un « nombre » est une expression"],
      disp:[2,0,3,1] },
    why:"Les quatre défis attaquent la même comparaison par quatre couches différentes : la cible (RANDOM), le verrou (readonly), la fondation du verrou (BASH_SUBSHELL), et le contexte lui-même (l’indice arithmétique). C’est la méthode d’audit complète : ne pas s’arrêter à la première protection venue, mais demander à chaque couche sur quoi elle repose — et si ce support, lui, peut bouger." },
  { id:"AOS-11", mod:"Bypassing Input Restrictions", t:"tr + eval : supprimer des caractères ne supprime pas le langage", sub:"Module Bypassing Input Restrictions (17 défis), défis 1 et 2 : Rhythm of Restriction et Odyssey of the Octal. Ressources du module : HackTricks « Bypass Bash Restrictions », référence Bash des expansions.",
    read:["Le module Bypassing Input Restrictions change de décor : 17 défis de restrictions d’entrée brutales. La famille dominante : la première ligne tapée par l’utilisateur est filtrée par tr, puis exécutée par eval. Le défi 1 supprime toutes les lettres, tous les chiffres et le slash — tr -d “[A-Za-z0-9/]” — avant l’exécution. Il reste la ponctuation, les opérateurs, les expansions : et avec les opérateurs du shell — redirections, tuyaux, substitutions, accolades — on peut encore composer des commandes. Supprimer des caractères ne supprime pas le langage.",
      "Le défi 2 ajoute le point à la liste des suppressions. La parade conceptuelle change alors d’alphabet : les nombres peuvent s’écrire autrement qu’en décimal. L’arithmétique du shell connaît l’octal — base 8 — et d’autres bases ; un code de caractère peut donc être reconstruit numériquement, puis reconverti en caractère par les mécanismes d’expansion, sans jamais écrire la lettre interdite. Le filtre raisonne en caractères ; l’attaquant raisonne en valeurs.",
      "Et au centre de la famille, le vrai coupable a un nom : eval. eval prend une chaîne et l’exécute comme du code — c’est sa fonction. Un filtre en amont ne fait que négocier la forme de ce code, jamais son existence. La leçon de défense est donc architecturale : ne jamais appliquer eval à une entrée extérieure, filtrée ou non. Les défis de ce module sont des démonstrations par l’absurde, répétées sous 17 formes : tout ce qui sépare une entrée d’eval finit par être contourné avec les moyens du shell lui-même."],
    term:"tr -d \"[A-Za-z0-9/]\" puis eval\n<span class=\"tdim\">Le filtre retire les lettres, les chiffres et le slash ; eval exécute ce qui reste. La ponctuation et les opérateurs suffisent au langage — c’est le filtre qui est naïf, pas le shell qui est faible.</span>",
    ex:{ type:"qcm", q:"Pourquoi les filtres de caractères en amont d’eval finissent-ils toujours par céder ?",
      opts:["Parce que tr contient des bogues connus", "Parce qu’eval exécute du code par construction, et que le shell offre toujours un autre encodage — ponctuation, expansions, bases numériques — pour exprimer la même commande avec les caractères restants", "Parce que les utilisateurs peuvent taper très vite"], ok:1 },
    why:"Un filtre par caractères négocie la forme, jamais le fond : tant qu’il reste un moyen d’exprimer une commande — et le shell en offre beaucoup — l’exécution suit. La seule défense réelle est de ne pas mettre d’eval sur le chemin d’une entrée. C’est la version shell d’une règle générale : ne transforme jamais une donnée en code, même après l’avoir « nettoyée »." },
  { id:"AOS-12", mod:"Bypassing Input Restrictions", t:"Bases numériques et chemins spéciaux : les alphabets de secours", sub:"Défis 3 à 6 : Riddle of the Radix, Whisper of the Withheld, Path of the Unseen, Dance of the Disallowed — les conversions de base, le tilde et le point.",
    read:["Les défis 3 à 6 explorent les alphabets de secours de façon systématique. Le défi 3 autorise les chiffres mais supprime lettres, point et slash : chaque base numérique — radix — devient une autre façon d’écrire la même valeur, et un nombre écrit en base 8, 10 ou 16 peut être converti puis reconverti en caractère. Le défi 4 rejoue le même filtre dans une fonction doit() et un répertoire temporaire ; le défi 6 resserre encore la vis en supprimant aussi le tilde et le point.",
      "Le défi 5, lui, autorise justement ce que les autres interdisent : le point et le tilde survivent au filtre. Or ~ désigne le répertoire personnel et . le répertoire courant — deux caractères qui sont déjà des chemins. Avec eux, on se déplace, on désigne des fichiers cachés, on reconstruit des adresses : le système de fichiers entier devient adressable avec un alphabet de deux signes, à condition de pouvoir écrire les noms — c’est là que les défis se combinent : chemins spéciaux d’un côté, encodages de l’autre.",
      "Retiens le principe unificateur de la famille : une restriction d’entrée ne se mesure pas au nombre de caractères interdits, mais à l’expressivité de ce qui reste. Deux caractères bien choisis — un opérateur et un chemin spécial — peuvent valoir un langage entier. En défense, cela signifie qu’une liste de caractères autorisés ne vaut que si l’on a raisonné sur tout ce que leurs combinaisons permettent — expansions, conversions, chemins — et pas seulement sur leur sens littéral."],
    ex:{ type:"qcm", q:"Pourquoi le tilde et le point, à eux seuls, donnent-ils déjà prise sur le système de fichiers ?",
      opts:["Parce qu’ils sont invisibles dans les journaux", "Parce que ~ désigne le répertoire personnel et . le répertoire courant : ce sont des chemins, et avec des chemins on se déplace et on désigne des fichiers", "Parce que tr ne peut pas les filtrer"], ok:1 },
    why:"Certains caractères du shell sont des raccourcis sémantiques, pas de la ponctuation : ~ et . portent des adresses. Les laisser passer « parce qu’ils sont inoffensifs » revient à laisser passer la navigation elle-même. C’est le même réflexe que pour les options des commandes : en audit, on évalue ce qu’un caractère fait, pas ce à quoi il ressemble." },
  { id:"AOS-13", mod:"Bypassing Input Restrictions", t:"Un alphabet minuscule suffit : expansions et historique", sub:"Défis 7, 8 et 9 : Veil of the Forbidden, Your Misplaced Memories, Exclamations of Execution — les filtres inversés et l’expansion d’historique.",
    read:["Les défis 7 et 8 inversent le filtre : au lieu de supprimer des caractères, tr -cd ne garde qu’un alphabet minuscule. Le défi 7 ne laisse survivre que _ $ } { ( ) # ; : < = + — et c’est déjà presque un langage : les expansions ${...} et $(...), les affectations, les comparaisons, les commentaires. Le défi 8 va à l’extrême : seuls - et ~ survivent. Il reste les options des commandes et le répertoire personnel — de quoi agir, et même de quoi retrouver des données « égarées » : variables d’environnement et historique vivent à portée de ces deux signes.",
      "Le défi 9 combine la contrainte de taille et la mémoire du shell : l’entrée est limitée à 5 caractères, lettres, chiffres, point, slash, tilde et tiret supprimés, puis eval. Mais le shell se souvient de ce qui a déjà été tapé : l’expansion d’historique — le point d’exclamation et ses formes — permet de rappeler et de réutiliser du texte antérieur sans le retaper. La limite porte sur chaque frappe ; l’historique, lui, n’a pas de limite de 5 caractères.",
      "La leçon commune : un terminal n’est pas une suite de lignes indépendantes, c’est un état — environnement, historique, répertoire courant — qui persiste entre les frappes. Filtrer chaque ligne isolément, c’est rater tout ce que l’état permet de reconstruire. En défense comme en audit, raisonne toujours sur la session entière, pas sur la ligne : c’est dans l’accumulation que les restrictions s’effondrent."],
    ex:{ type:"qcm", q:"Quel rôle l’historique du shell joue-t-il face à une entrée limitée à 5 caractères ?",
      opts:["Aucun : l’historique est désactivé dans les shells restreints", "Il permet de rappeler du texte déjà tapé et de le réutiliser sans le retaper : la limite s’applique à chaque frappe, pas à ce que la session a déjà en mémoire", "Il permet de dépasser la limite en tapant plus vite"], ok:1 },
    why:"L’expansion d’historique transforme quelques caractères — un point d’exclamation et une référence — en un texte entier déjà présent dans la session. C’est la démonstration que la restriction portait sur le mauvais objet : la frappe, alors que l’exécution consomme l’état. Toute défense qui ignore l’état — historique, environnement, fichiers temporaires — laisse une mémoire à disposition de l’attaque." },
  { id:"AOS-14", mod:"Bypassing Input Restrictions", t:"Les filtres par ligne ne voient pas l’état", sub:"Défis 10 à 13 : Sensing of Secrets, A String of Secrecy, The Secret Commanded, The Stumble From Safety — seuls les lignes commençant par echo ou read survivent.",
    read:["Les défis 10 à 13 changent de filtre : ce n’est plus un alphabet, ce sont les lignes entières qui sont triées. Le script fourni par l’utilisateur est d’abord réduit à quelques caractères autorisés — retours à la ligne, espace, $, -, / et lettres — puis seules les lignes commençant par echo ou read survivent, avant exécution. Une liste blanche de commandes « inoffensives », en apparence : afficher et lire, que peut-on faire de mal avec ça ?",
      "Tout, si l’on raisonne en état plutôt qu’en lignes. echo écrit ce qu’on lui donne et read reçoit ce qu’on lui présente : à eux deux, ils permettent de « suggérer » d’abord un contenu, ligne après ligne, puis de l’« exiger » au moment où l’état construit devient exécutable. Le filtre voit des lignes anodines ; l’exécution voit le résultat accumulé. Les variantes resserrent l’alphabet — minuscules seulement (défi 11), le $ retiré (défi 12), les chiffres autorisés (défi 13) — sans changer le principe.",
      "C’est la forme la plus générale de la leçon du module : un filtre qui juge des unités isolées — caractères, lignes, requêtes — ne voit pas les effets composés. En défense, la question à poser à tout filtre est : « que peut-on construire en plusieurs fois avec ce que tu laisses passer à chaque fois ? ». Si la réponse est « un programme », le filtre est une passoire, quelle que soit la finesse de son tri."],
    ex:{ type:"qcm", q:"Pourquoi un filtre qui ne laisse passer que des lignes echo et read peut-il quand même laisser construire une attaque ?",
      opts:["Parce que echo et read sont des commandes root déguisées", "Parce que le filtre juge chaque ligne isolément, alors que l’exécution consomme l’état accumulé : suggérer un contenu ligne par ligne, puis l’exiger, compose un tout qu’aucune ligne seule ne montrait", "Parce que les lignes longues échappent au filtre"], ok:1 },
    why:"La liste blanche portait sur des verbes, pas sur des effets. echo dépose, read charge : deux opérations « de lecture-écriture » suffisent à assembler, dans l’état de la session, ce que le filtre interdisait d’écrire d’un bloc. C’est exactement le même angle mort que pour l’historique du défi 9 : la sécurité d’un système séquentiel ne se juge jamais ligne à ligne." },
  { id:"AOS-15", mod:"Bypassing Input Restrictions", t:"Cinq caractères suffisent : la brièveté n’est pas une protection", sub:"Défis 14 à 17 : Precision of Parameters, Brevity’s Enigma, Essense of Economy, Mirage of Minimalism — les entrées ultra-courtes exécutées par sh -c.",
    read:["Les défis 14 à 17 poussent la contrainte à son minimum : des entrées de 4 ou 5 caractères au maximum, exécutées par sh -c. Le décor du défi 14 est pourtant soigné : répertoire temporaire nettoyé, HOME redéfini, OLDPWD supprimé, et le flag copié dans ce répertoire. Mais cinq caractères suffisent à exprimer une lecture de fichier : les commandes Unix sont courtes, les jokers remplacent les noms, et le répertoire courant fait le reste. Le défi 16 déplace le flag à son emplacement habituel, /flag ; les défis 15 et 17 descendent à 4 caractères, en boucle interactive.",
      "Ce que la famille démontre, c’est qu’une limite de longueur n’est pas une limite d’expressivité. Le vocabulaire minimal du shell — une commande d’un ou deux caractères, un joker, une redirection — forme déjà un langage complet pour lire, écrire et lancer. Les concepteurs de restrictions pensent en « que peut-on bien faire avec si peu ? » ; la réponse du shell est : presque tout, parce que ses briques sont minuscules par design — c’est même sa philosophie historique.",
      "En défense, la conclusion rejoint celle des défis précédents : ni la longueur, ni l’alphabet, ni la forme des lignes ne font une frontière. Les frontières réelles sont d’une autre nature : qui exécute, avec quels droits, dans quel répertoire, avec quel accès au système de fichiers. Un sh -c sur une entrée extérieure est une exécution offerte ; la seule question est l’étendue des dégâts possibles — et elle se règle par les privilèges, pas par les caractères."],
    ex:{ type:"order", q:"Remets dans l’ordre la famille des entrées ultra-courtes :",
      items:["Le décor : répertoire temporaire nettoyé, HOME redéfini, OLDPWD supprimé, flag copié sur place", "L’entrée tombe à 5 caractères, exécutée par sh -c dans ce répertoire", "Le flag retourne à /flag, toujours en 5 caractères maximum", "La boucle interactive descend à 4 caractères : la variante la plus courte"],
      disp:[2,0,3,1] },
    why:"Du décor le plus verrouillé à l’entrée la plus courte, la famille montre une constante : rien ne casse. Cinq caractères, puis quatre, suffisent parce que le shell compose des briques minuscules — commandes d’une lettre, jokers, redirections. La longueur d’une entrée n’a jamais été une mesure de son pouvoir ; seuls les droits du processus qui l’exécute en sont une." },
  { id:"AOS-16", mod:"Inputting a Surprise", t:"Les noms de fichiers sont des entrées", sub:"Module Inputting a Surprise (7 défis), défis 1 et 2 : Dance of the Disguised et Script of the Silent. Ressources du module : BashPitfalls (wiki wooledge), sh_tricks d’etalabs.",
    read:["Le module Inputting a Surprise change de vecteur : ce n’est plus ce que l’utilisateur tape, c’est ce qu’il fait exister. Le défi 1 copie les fichiers d’un répertoire puis les affiche un par un via ls notflag* | while read FILE, en rejetant tout fichier contenant une accolade. Mais les noms de fichiers sont des entrées comme les autres : un nom avec des espaces est découpé par read sur IFS, un nom avec un retour à la ligne se fait passer pour deux fichiers, et le contenu « déguisé » par son nom échappe au contrôle qui croyait l’avoir lu.",
      "Le défi 2 joue sur les arguments : printf -v BACKUP_DIR “$1” écrit l’argument dans une variable, puis tar cvf /tmp/backup “$BACKUP_DIR” l’utilise comme membre de l’archive. Un argument qui commence par un tiret n’est plus une donnée pour la commande qui le reçoit : c’est une option. tar, comme presque tous les outils Unix, interprète ce qui commence par - comme un ordre de changer de comportement. L’« entrée surprise » est là : la donnée change de nature en changeant de main.",
      "Les défenses sont des classiques à graver : traiter les noms de fichiers comme hostiles — guillemets partout, et pour les noms extrêmes, find avec -print0 et read -d ‘’ —, et séparer les options des données avec le marqueur -- quand l’outil le permet, pour que plus rien de ce qui suit ne puisse être lu comme une option. Un script qui manipule des fichiers créés par d’autres est un script qui analyse des entrées adverses — même quand « les autres » ont juste des habitudes de nommage exotiques."],
    term:"tar cvf /tmp/backup \"$BACKUP_DIR\"   ← si la valeur commence par -, tar lit une option\ntar cvf /tmp/backup -- \"$BACKUP_DIR\" ← -- clôt les options : la suite est une donnée\n<span class=\"tdim\">Le tiret initial change la nature d’un argument. -- est la frontière que le programmeur peut tracer entre ordres et données.</span>",
    ex:{ type:"qcm", q:"Pourquoi un nom de fichier peut-il casser la boucle ls ... | while read FILE du défi 1 ?",
      opts:["Parce que ls trie les noms dans le désordre", "Parce que read découpe sur IFS : un nom avec des espaces arrive en plusieurs morceaux, et un retour à la ligne dans un nom le fait passer pour deux fichiers — le script ne voit plus les vrais fichiers", "Parce que les noms longs sont tronqués par le shell"], ok:1 },
    why:"Les noms de fichiers autorisent presque tous les caractères, espaces et retours à la ligne compris. Une boucle qui les lit ligne à ligne, mot à mot, analyse donc une entrée que le créateur des fichiers contrôle entièrement. C’est la version « système de fichiers » de la variable non citée : ce qui n’est pas protégé sera réinterprété — par read ici, par le découpage ailleurs." },
  { id:"AOS-17", mod:"Inputting a Surprise", t:"Les namerefs : écrire dans la variable d’un autre", sub:"Défis 3 et 4 : One Single Slice et The Treacherous Title — declare -n et l’indirection contre les variables en lecture seule.",
    read:["Les défis 3 et 4 introduisent l’indirection la plus élégante — et la plus traîtresse — de bash : les références de nom, ou namerefs. declare -n PTR=“$VAR” fait de PTR non pas une variable ordinaire, mais un alias vivant : assigner PTR=“$VAL”, c’est écrire dans la variable que VAR désigne. Le défi 3 est cette « tranche unique » : une seule affectation, à travers la référence, atteint une cible que le code n’a jamais nommée directement.",
      "Le défi 4 verrouille le décor : toutes les variables existantes sont rendues en lecture seule (declare -r). Mais readonly protège un nom, pas ce qu’il désigne : en visant, via une nameref fraîchement créée, une variable qui n’a pas été verrouillée — ou la mécanique elle-même —, l’affectation passe par l’indirection là où l’accès direct était fermé. Le verrou est sur la porte ; la référence passe par la fenêtre que le langage a prévue.",
      "La leçon pour qui écrit des scripts : l’indirection — namerefs, expansion indirecte ${!nom}, declare dans une portée locale — crée des chemins d’écriture que la lecture linéaire du code ne montre pas. Auditer un script qui utilise des références, c’est suivre chaque alias jusqu’à sa cible réelle, y compris quand la cible est choisie par une donnée extérieure. Et pour qui défend : verrouiller des noms ne suffit jamais quand le langage permet de les désigner autrement."],
    ex:{ type:"qcm", q:"Que se passe-t-il quand on assigne une valeur à une nameref ?",
      opts:["La nameref stocke la valeur comme une variable ordinaire", "L’affectation écrit dans la variable désignée par la référence : la nameref est un alias vivant de sa cible, quelle qu’elle soit", "La valeur est copiée dans toutes les variables du script"], ok:1 },
    why:"Une nameref n’est pas un pointeur figé vers une valeur : c’est un nom de variable résolu à chaque usage. Écrire dans la référence, c’est écrire dans la cible du moment — y compris une cible que le verrouillage readonly des autres variables ne couvre pas, puisque c’est le nom d’accès qui change, pas la cible. Toute indirection doit donc être auditée comme un chemin d’écriture à part entière." },
  { id:"AOS-18", mod:"Inputting a Surprise", t:"basename ne nettoie pas un chemin, et read écrase sans prévenir", sub:"Défis 5, 6 et 7 : The Dangling Danger, The Evil End, An Eroded Erasure — ce qui pend à la fin du chemin, la barre oblique finale, et la variable érodée.",
    read:["Les défis 5 et 6 tournent autour d’un « nettoyage » de chemin : cat /$(basename “$1”) — basename ne retient que le dernier élément d’un chemin — avec rejet des arguments se terminant par flag. Ce qui « pend » à la fin du chemin décide donc du fichier lu : basename jette tout le reste, et c’est précisément ce reste jeté qui portait l’intention. Le défi 6 ajoute le rejet des chemins se terminant par / : la barre oblique finale change l’interprétation d’un chemin — répertoire contre fichier — et le filtre doit donc aussi raisonner sur elle.",
      "Le défi 7 est d’une simplicité trompeuse : read FLAG < /flag charge le secret, puis un second read FLAG attend l’entrée de l’utilisateur — et écrase la variable. L’entrée peut en outre contenir des caractères d’effacement, des retours arrière, qui « érodent » la valeur affichée ensuite par echo “$FLAG” : ce qui est lu, ce qui est stocké et ce qui est affiché sont trois choses différentes dès que l’entrée contient des caractères de contrôle.",
      "Trois défenses, une par défi : ne jamais reconstruire un chemin sensible à partir d’un morceau nettoyé — valider le chemin entier, ou travailler avec une liste blanche de noms ; traiter la forme complète d’un chemin, y compris sa fin ; et ne jamais réutiliser pour une entrée extérieure une variable qui porte déjà un secret — read écrase sans prévenir, et l’entrée standard n’est jamais propre."],
    ex:{ type:"qcm", q:"Quel est le défaut de fond de cat /$(basename “$1”) comme « nettoyage » ?",
      opts:["basename est une commande lente", "basename ne garde que le dernier élément du chemin : c’est la fin du chemin fourni qui décide du fichier lu, et tout ce qui précédait — l’intention, le contexte — est jeté", "Le rejet des arguments finissant par flag est trop strict"], ok:1 },
    why:"Nettoyer en tronquant, c’est décider à la place de l’entrée : le morceau conservé devient la vérité du programme. C’est le même défaut que la désinfection par troncature du lanceur (défi 10 d’Abusing Expansion) : ce qui reste après nettoyage peut désigner exactement ce qu’on voulait interdire. Un chemin se valide entier — ou se choisit dans une liste — il ne se « raccourcit » pas vers la sécurité." },
  { id:"AOS-19", mod:"Other Challenges", t:"Les secrets ne voyagent pas en ligne de commande", sub:"Module Other Challenges (6 défis), défis 1 à 3 : Secrets of the Processes, Puzzle of the Perverse Predicates, The Flag Resting Safely — processus visibles, prédicat renversé, destination verrouillée.",
    read:["Le dernier module, Other Challenges, rassemble six défis hors catégories. Le premier pose une devinette : taper le flag, vérifié par grep -q “$(< /flag)” sur la première ligne. Son enseignement est ailleurs : les processus et leurs arguments sont visibles de l’extérieur — ps, /proc — et un secret qui transite par une ligne de commande ou une entrée observable peut être lu par qui sait regarder. Les secrets ne doivent jamais voyager en clair dans les arguments d’un processus.",
      "Le deuxième défi retourne un test en porte d’entrée : [ “$1” != “$FLAG” ] && echo “Incorrect Guess. Goodbye!” || bash -i — deviner juste ne donne pas un message de victoire, mais un shell interactif. C’est la version ludique d’une vérité d’audit : un prédicat — un simple test d’égalité — peut être la seule chose entre l’extérieur et un shell ; sa logique, son sens, ses cas limites méritent la même attention qu’un mot de passe.",
      "Le troisième défi inverse la perspective : il faut choisir où écrire le flag. La destination est filtrée — minuscules, chiffres et / seulement — doit être un chemin absolu, et chaque composante du chemin est vérifiée : propriétaire, groupe, permissions, noms interdits comme proc ou fd ; puis le chemin est rendu inaccessible (chmod 000) avant que le flag n’y soit écrit. La leçon : la sécurité d’un fichier ne tient pas qu’à ses propres permissions, mais à tout son chemin — chaque répertoire parent est un maillon."],
    term:"ps aux · /proc/<pid>/cmdline\n<span class=\"tdim\">Les arguments des processus sont lisibles de l’extérieur. Un secret passé en argument est un secret affiché.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la sécurisation de la destination du défi 3 :",
      items:["Filtrer la destination : minuscules, chiffres et /, chemin absolu exigé", "Vérifier chaque composante du chemin : propriétaire, groupe, permissions, noms interdits", "Rendre le chemin inaccessible avec chmod 000", "Écrire le flag à la destination ainsi verrouillée"],
      disp:[2,0,3,1] },
    why:"Filtrer, vérifier maillon par maillon, verrouiller, puis seulement écrire : l’ordre est la défense. Un fichier aux permissions parfaites dans un répertoire inscriptible par tous reste remplaçable ; c’est le chemin entier qui constitue la surface. Le défi le fait vérifier composante par composante — le réflexe exact à appliquer avant de déposer un secret, une clé ou une sauvegarde quelque part." },
  { id:"AOS-20", mod:"Other Challenges", t:"Shell restreint, TOCTOU et bilan du dojo", sub:"Défis 4 à 6 : The Scream of Silence, Deception Born of Wisdom, Beam me up Sensei — bash --restricted, le script vérifié mille fois, et les codes de sortie. Synthèse des 55 défis.",
    read:["Le défi 4 enferme le joueur dans un shell restreint : exec /bin/bash --restricted avec un fichier d’initialisation qui désactive presque tous les builtins (enable -n), remplace des mots-clés par des alias, et invalide le PATH, piège anti-sous-shell en prime. Le mode restreint de bash interdit de changer de répertoire, de modifier PATH ou de rediriger vers des chemins absolus — mais un verrouillage n’est jamais total : les builtins restants, les redirections autorisées et les expansions forment toujours un espace de manœuvre. Un shell restreint réduit la surface ; il ne la supprime pas.",
      "Le défi 5 est la leçon de TOCTOU du dojo : un script d’installation est téléchargé en boucle — entre 1337 et 2336 vérifications — et contrôlé ligne par ligne par un filtre qui n’autorise que des lignes touch, echo ou sleep suivies de caractères simples, avant d’être exécuté par sh. Vérifier puis exécuter, ce sont deux moments différents : le contenu peut changer entre le contrôle et l’exécution, et un filtre de lignes ne voit de toute façon pas l’effet combiné des lignes. Répéter la vérification deux mille fois n’y change rien : ce n’est pas le nombre de contrôles qui protège, c’est leur atomicité avec l’usage.",
      "Le défi 6 referme le dojo sur l’arithmétique et les codes de sortie : une expression validée par une expression régulière de forme stricte est évaluée par $[...] — l’ancienne forme d’expansion arithmétique — et le résultat devient le code de sortie du programme, limité à 0-255 par construction. Bilan du dojo entier : bash évalue, expanse et réinterprète à chaque couche — guillemets, arithmétique, indices, formats, historique. Ce dojo open source (licence BSD-2-Clause) t’a appris à lire ces couches comme un auditeur : c’est exactement le regard qu’il faudra porter sur chaque script rencontré en mission."],
    term:"vérifier ≠ exécuter : entre les deux, le contenu peut changer\n<span class=\"tdim\">TOCTOU — Time Of Check, Time Of Use. Le défi 5 vérifie le script jusqu’à 2336 fois ; il suffit qu’il change une fois, au bon moment.</span>",
    ex:{ type:"qcm", q:"Dans le défi 5, pourquoi la vérification répétée du script ne protège-t-elle pas son exécution ?",
      opts:["Parce que le filtre autorise trop de commandes différentes", "Parce que vérifier et exécuter sont deux moments distincts : le contenu peut changer entre le contrôle et l’usage — et un filtre ligne par ligne ne voit pas l’effet combiné des lignes", "Parce que 2336 vérifications ne suffisent pas ; il en faudrait 10 000"], ok:1 },
    why:"C’est le TOCTOU dans sa forme la plus pure : Time Of Check, Time Of Use. La garantie d’un contrôle ne vaut qu’à l’instant du contrôle ; si l’objet peut changer ensuite — fichier retéléchargé, cible modifiée — l’exécution consomme autre chose que ce qui a été vérifié. La parade n’est jamais « vérifier plus », mais vérifier la copie exacte qui sera exécutée, au plus près de l’exécution — ou rendre l’objet immuable entre les deux." }
];
